/// The capabilities a location might have.
public enum LocationCapability: String, Codable {
	/// The capability to process credit card transactions with Square.
	case CREDIT_CARD_PROCESSING
	/// The capability to receive automatic transfers from Square.
	case AUTOMATIC_TRANSFERS
	/// The capability to process unlinked refunds with Square.
	case UNLINKED_REFUNDS
}

/// A location's status.
public enum LocationStatus: String, Codable {
	/// A location that is active for business.
	case ACTIVE
	/// A location that is not active for business. Inactive locations provide historical information. Hide inactive locations unless the user has requested to see them.
	case INACTIVE
}

/// A location's type.
public enum LocationType: String, Codable {
	/// A place of business with a physical location.
	case PHYSICAL
	/// A place of business that is mobile, such as a food truck or online store.
	case MOBILE
}

